import React from 'react';
import { Handle, Position } from 'reactflow';
import { getNodeStyle, getTypeDisplayText } from '../utils/dataConverter';

const CustomNode = ({ data }) => {
  const style = getNodeStyle(data);
  const typeText = getTypeDisplayText(data);
  
  return (
    <div style={style}>
      {/* Connection handles */}
      <Handle 
        type="target" 
        position={Position.Top} 
        style={{ background: '#555' }} 
      />
      
      {/* Node content */}
      <div style={{ textAlign: 'center' }}>
        <div style={{ 
          fontWeight: 'bold', 
          marginBottom: '4px',
          fontSize: '16px'
        }}>
          {data.name}
        </div>
        
        <div style={{ 
          fontSize: '12px', 
          color: '#6b7280',
          marginBottom: '8px',
          textTransform: 'uppercase',
          letterSpacing: '0.5px'
        }}>
          {typeText}
        </div>
        
        {/* Additional details */}
        {data.uuaa && (
          <div style={{ 
            fontSize: '11px', 
            color: '#4b5563',
            marginBottom: '2px'
          }}>
            UUAA: {data.uuaa}
          </div>
        )}
        
        {data.code && (
          <div style={{ 
            fontSize: '11px', 
            color: '#4b5563',
            marginBottom: '2px'
          }}>
            Code: {data.code}
          </div>
        )}
        
        {data.className && (
          <div style={{ 
            fontSize: '11px', 
            color: '#4b5563',
            fontStyle: 'italic'
          }}>
            {data.className}
          </div>
        )}
        
        {data.description && (
          <div style={{ 
            fontSize: '10px', 
            color: '#9ca3af',
            marginTop: '6px',
            fontStyle: 'italic',
            maxWidth: '160px',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            whiteSpace: 'nowrap'
          }}>
            {data.description}
          </div>
        )}
      </div>
      
      <Handle 
        type="source" 
        position={Position.Bottom} 
        style={{ background: '#555' }} 
      />
    </div>
  );
};

export default CustomNode;